FUNCTION UNDER TEST:
Name: buffer_trim_left
Signature: void buffer_trim_left(buffer_t *self)
Description: /**
 * @brief Removes leading whitespace from the buffer data.
 *
 * Advances the buffer's data pointer past any leading whitespace characters,
 * effectively trimming spaces, tabs, and other isspace() characters from the start.
 * The buffer contents are not modified; only the data pointer is updated.
 *
 * @param self Pointer to a buffer_t structure. Must not be NULL. The data pointer
 *             within the buffer is modified to skip leading whitespace.
 *
 * @return None.
 *
 * @note The function does not allocate or free memory. The caller retains ownership
 *       of the buffer and is responsible for its lifecycle.
 */
Dependencies: None

FUNCTION IMPLEMENTATION:
```c
// C program for the function called buffer_trim_left
// Contains target function implementation and dependency signatures

#include <string.h>
#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <ctype.h>
#include <sys/types.h>
#include "buffer.h"

// Target function implementation
void
buffer_trim_left(buffer_t *self) {
  int c;
  while ((c = *self->data) && isspace(c)) {
    ++self->data;
  }
}

